import{_ as s,C as i,o as n,c as l,j as r,a as o,E as a,a2 as d}from"./chunks/framework.BxGh02fV.js";const v=JSON.parse('{"title":"Qualité","description":"","frontmatter":{"title":"Qualité"},"headers":[],"relativePath":"agent/qualite.md","filePath":"agent/qualite.md"}'),c={name:"agent/qualite.md"};function u(f,e,p,h,m,q){const t=i("Ask");return n(),l("div",null,[e[0]||(e[0]=r("h1",{id:"qualite",tabindex:"-1"},[o("Qualité "),r("a",{class:"header-anchor",href:"#qualite","aria-label":'Permalink to "Qualité"'},"​")],-1)),e[1]||(e[1]=r("p",null,"Ce parcours garde le projet cohérent : le code ne change pas sans tâche en cours, le registre ne se contredit pas, et les sous-agents n'écrivent pas n'importe où. Vous y venez avant un commit, après une longue session, ou pour installer les garde-fous.",-1)),e[2]||(e[2]=r("h2",{id:"ce-que-vous-demandez-a-l-agent",tabindex:"-1"},[o("Ce que vous demandez à l'agent "),r("a",{class:"header-anchor",href:"#ce-que-vous-demandez-a-l-agent","aria-label":`Permalink to "Ce que vous demandez à l'agent"`},"​")],-1)),a(t,{say:"Y a-t-il de la dérive ? J'ai l'impression d'avoir modifié du code sans tâche.",verb:"effortless_drift_check",family:"qualite"}),a(t,{say:"Installe le hook qui m'empêche de committer du code sans tâche en cours.",verb:"effortless_drift_hook_install",family:"qualite"}),a(t,{say:"Vérifie la cohérence du registre : épics, stories, tâches.",verb:"effortless_validate_project",family:"qualite"}),a(t,{say:"Qu'est-ce que tu répareras si on lance la réparation ? Ne touche à rien pour l'instant.",verb:"effortless_health_repair",family:"qualite",args:'{"apply":false}'}),a(t,{say:"OK, applique les réparations.",verb:"effortless_health_repair",family:"qualite",args:'{"apply":true}'}),a(t,{say:"Confine les sous-agents : ils ne doivent pas écrire directement dans le projet.",verb:"effortless_confinement_hook_install",family:"qualite"}),a(t,{say:"Régénère le registre des foyers du code.",verb:"effortless_foyer_registry",family:"qualite"}),e[3]||(e[3]=d('<h2 id="ce-que-fait-l-agent" tabindex="-1">Ce que fait l&#39;agent <a class="header-anchor" href="#ce-que-fait-l-agent" aria-label="Permalink to &quot;Ce que fait l&#39;agent&quot;">​</a></h2><h3 id="detecter-la-derive" tabindex="-1">Détecter la dérive <a class="header-anchor" href="#detecter-la-derive" aria-label="Permalink to &quot;Détecter la dérive&quot;">​</a></h3><p><a href="/Effortless/reference/mcp/qualite.html#drift-check"><code>effortless_drift_check</code></a> lit l&#39;état git du projet et de chaque stack qui a son propre dépôt. Il y a dérive quand du code est modifié alors qu&#39;aucune tâche n&#39;est <strong>En cours</strong>. Les fichiers de <code>.effortless/</code> et de <code>blueprints/</code> ne comptent pas comme du code. La réponse dit aussi si le hook anti-dérive est installé sur chaque dépôt. Le verbe ne fait que lire.</p><h3 id="installer-le-hook-anti-derive" tabindex="-1">Installer le hook anti-dérive <a class="header-anchor" href="#installer-le-hook-anti-derive" aria-label="Permalink to &quot;Installer le hook anti-dérive&quot;">​</a></h3><p><a href="/Effortless/reference/mcp/qualite.html#drift-hook-install"><code>effortless_drift_hook_install</code></a> pose un hook git <code>pre-commit</code> sur le dépôt du projet et sur chaque stack qui a son propre dépôt. Quand du code est en index sans tâche en cours, il refuse le commit. Quand une tâche est en cours, il affiche laquelle portera le commit. Il ne remplace jamais un hook <code>pre-commit</code> qui n&#39;est pas celui d&#39;Effortless.</p><h3 id="valider-le-registre" tabindex="-1">Valider le registre <a class="header-anchor" href="#valider-le-registre" aria-label="Permalink to &quot;Valider le registre&quot;">​</a></h3><p><a href="/Effortless/reference/mcp/qualite.html#validate-project"><code>effortless_validate_project</code></a> audite les épics, stories et tâches et rend les anomalies classées par gravité : bloquante, fausse, oubli probable, héritage d&#39;avant une règle. Il ne fait que lire.</p><h3 id="reparer" tabindex="-1">Réparer <a class="header-anchor" href="#reparer" aria-label="Permalink to &quot;Réparer&quot;">​</a></h3><p><a href="/Effortless/reference/mcp/qualite.html#health-repair"><code>effortless_health_repair</code></a> refait le même diagnostic et annonce ce qu&#39;il réparerait. Sans <code>apply</code>, rien n&#39;est modifié. Avec <code>apply: true</code>, il applique les seules réparations qui ne demandent aucune décision : clôturer une story dont toutes les tâches sont faites, clôturer un épic dont toutes les stories sont closes. Le reste demeure dans les anomalies. L&#39;agent annonce d&#39;abord, puis n&#39;applique qu&#39;après votre accord.</p><h3 id="confiner-les-sous-agents" tabindex="-1">Confiner les sous-agents <a class="header-anchor" href="#confiner-les-sous-agents" aria-label="Permalink to &quot;Confiner les sous-agents&quot;">​</a></h3><p><a href="/Effortless/reference/mcp/qualite.html#confinement-hook-install"><code>effortless_confinement_hook_install</code></a> installe un hook qui refuse à un sous-agent d&#39;écrire directement dans le projet (outils d&#39;écriture de fichiers). Il travaille dans un worktree, et son travail n&#39;entre dans le dépôt qu&#39;à la réintégration, quand la barre est verte (voir <a href="/Effortless/agent/code.html">Code et stacks</a>). Le script est posé dans <code>.claude/hooks/</code> et déclaré dans <code>.claude/settings.json</code>, que le verbe complète sans jamais le remplacer. Le hook ne couvre pas les commandes shell et ne confine pas l&#39;agent principal.</p><h3 id="tenir-le-registre-des-foyers" tabindex="-1">Tenir le registre des foyers <a class="header-anchor" href="#tenir-le-registre-des-foyers" aria-label="Permalink to &quot;Tenir le registre des foyers&quot;">​</a></h3><p><a href="/Effortless/reference/mcp/qualite.html#foyer-registry"><code>effortless_foyer_registry</code></a> balaie le code de production à la recherche des foyers marqués, et rend aussi son angle mort : fichiers sans marqueur, fonctions publiques hors foyer. Par défaut (<code>write_page</code> absent ou vrai), il écrit la page scellée dans le dossier de pages que déclare la documentation utilisateur. Avec <code>write_page: false</code>, il rend le contenu sans rien écrire. Le balayage lit les fichiers Rust.</p><h2 id="ce-que-vous-obtenez" tabindex="-1">Ce que vous obtenez <a class="header-anchor" href="#ce-que-vous-obtenez" aria-label="Permalink to &quot;Ce que vous obtenez&quot;">​</a></h2><ul><li>Un verdict de dérive et une liste de fichiers, qui sont ceux de l&#39;écran <a href="/Effortless/guide/drift.html">Dérive</a> : l&#39;agent et vous voyez la même chose.</li><li>Un hook <code>pre-commit</code> dans <code>.git/hooks/</code> de chaque dépôt suivi.</li><li>Un rapport d&#39;anomalies, et, après accord, des épics et stories clos.</li><li>Pour le confinement : <code>.claude/hooks/confine-subagents.cjs</code> et son entrée dans <code>.claude/settings.json</code>.</li><li>Pour les foyers : une page de documentation dérivée, ou son contenu en réponse.</li></ul><h2 id="quand-l-agent-est-refuse" tabindex="-1">Quand l&#39;agent est refusé <a class="header-anchor" href="#quand-l-agent-est-refuse" aria-label="Permalink to &quot;Quand l&#39;agent est refusé&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Situation</th><th>Ce que dit le refus</th><th>Ce qu&#39;il faut faire</th></tr></thead><tbody><tr><td>Aucun projet Effortless trouvé depuis le dossier de travail</td><td><code>mcp:racineProjetIntrouvable</code></td><td>Renseigner <code>EFFORTLESS_PROJECT</code> si le projet existe ailleurs, sinon <code>effortless_init</code>.</td></tr><tr><td>Hook <code>pre-commit</code> déjà présent et qui n&#39;est pas celui d&#39;Effortless</td><td><code>drift:foreignHook</code></td><td>Retirer ou renommer ce hook, puis relancer <code>effortless_drift_hook_install</code>.</td></tr><tr><td>Un dépôt à équiper n&#39;est pas un dépôt git</td><td><code>drift:notAGitRepo</code></td><td>Faire <code>git init</code> dans ce dossier, ou retirer <code>git: true</code> de la stack.</td></tr><tr><td>Fichier du hook de confinement qui n&#39;est pas le nôtre</td><td><code>confinement:hookForeign</code></td><td>Retirer ou renommer ce fichier, puis relancer <code>effortless_confinement_hook_install</code>.</td></tr><tr><td><code>.claude/settings.json</code> n&#39;est pas un objet JSON</td><td><code>confinement:settingsNotAnObject</code></td><td>Corriger ce fichier, puis relancer.</td></tr><tr><td>Dossier qui n&#39;est pas un projet Effortless valide</td><td>« Pas un projet Effortless valide. »</td><td>Vérifier <code>effortless.json</code>.</td></tr><tr><td>Registre des foyers : binaire plus ancien que le code du dépôt</td><td><code>foyer:binairePerime</code></td><td>Reconstruire (<code>cargo build --bin app</code>) puis relancer. Ce garde-fou concerne surtout le dépôt de développement d&#39;Effortless lui-même.</td></tr><tr><td>Registre des foyers : aucune documentation utilisateur déclarée</td><td><code>userDoc:usage</code> (« aucune stack ne porte de userdoc.json »)</td><td>Déclarer la documentation utilisateur d&#39;une stack (voir <a href="/Effortless/agent/documentation.html">Documentation</a>), ou demander le contenu seul avec <code>write_page: false</code>.</td></tr></tbody></table>',17))])}const b=s(c,[["render",u]]);export{v as __pageData,b as default};
